//		{Method: "Store", Name: "my-claim",
//			Claim:    "a sentence stating exactly what this check proves",
//			Run:      myClaimBody,
//			ProvenBy: BrokenMixed("an implementation that breaks it", newBroken)},
//	}
type MixedChecks []MixedCheck

func (c MixedChecks) applyTo(rc *mixedRunConfig) {
	rc.rows = append(rc.rows, c...)
}

// MixedCheck is one check you wrote. The body is a plain named
// function; which field you put it in decides what it is handed.
//
// Every field down to Argued is documented on [suite.Row], which is
// what this becomes when the run binds it. The fields after them are this
// interface's own — they name the types its methods draw — and are
// documented here.
type MixedCheck struct {
	Method       string
	Name         string
	Claim        string
	Run          func(tb testing.TB, s Mixed, fx MixedFixture)
	RunWith      func(tb testing.TB, sub MixedSubject, fx MixedFixture)
	Class        suite.Class
	Needs        suite.Caps
	ProvenBy     MixedDefect
	ProvenReason string
	Argued       string

	// Prop is a body whose inputs are drawn rather than fixed, run many
	// times with the draws shrunk on failure. Report through the PropT
	// and not through a testing.TB: shrinking works by replaying draws, and
	// a failure raised anywhere else is one the run cannot narrow.
	//
	// Requires Method, like Run.
	Prop func(rt *PropT, s Mixed, fx MixedFixture)

	// PropStore is Prop with Store's own argument already drawn
	// from the pool the generated checks draw it from — so an override you
	// set on the run reaches your property too. Fixes the check's scope to
	// Store, so leave Method empty.
	PropStore func(rt *PropT, s Mixed, value pointintime.Value)

	// PropGet is Prop with Get's own argument already drawn
	// from the pool the generated checks draw it from — so an override you
	// set on the run reaches your property too. Fixes the check's scope to
	// Get, so leave Method empty.
	PropGet func(rt *PropT, s Mixed, key string)
}

// mixedMethods is the interface's method names, used to catch a typo in
// a check's Method field before the run starts.
//
// Without it a misspelled name would be accepted — it looks like any
// other method name — and the check would be filed under a method that
// does not exist, where nobody could find or drop it.
var mixedMethods = suite.NewNameSet("Mixed", mixedStore, mixedGet)

// bind converts one of your checks into the form the runner uses, tying
// it to this run's sample inputs — which is what lets a check you wrote
// see the same values, and the same overrides, as the generated ones.
func (c MixedCheck) bind(
	fx MixedFixture,
) (suite.Check[Mixed], error) {
	b := suite.BindRow(suite.Row[Mixed, MixedFixture]{
		Method: c.Method, Name: c.Name, Claim: c.Claim,
		Run: c.Run, RunWith: c.RunWith,
		Class: c.Class, Needs: c.Needs,
		Proven: c.ProvenBy != nil, ProvenReason: c.ProvenReason, Argued: c.Argued,
	}, fx, mixedMethods)
	b.Offers("Prop, PropStore, PropGet")
	if fn := c.Prop; fn != nil {
		b.ScopedWith("Prop", c.Method, func(tb testing.TB, sub suite.Subject[Mixed]) {
			model.Check(tb, func(rt *PropT) {
				fn(rt, sub.New(tb), fx)
			})
		})
	}
	if fn := c.PropStore; fn != nil {
		b.Fixed(suite.MethodID(mixedStore, c.Name),
			func(tb testing.TB, sub suite.Subject[Mixed]) {
				model.Check(tb, func(rt *PropT) {
					fn(rt, sub.New(tb), mixedModelValues(fx).Draw(rt, "value"))
				})
			})
	}
	if fn := c.PropGet; fn != nil {
		b.Fixed(suite.MethodID(mixedGet, c.Name),
			func(tb testing.TB, sub suite.Subject[Mixed]) {
				model.Check(tb, func(rt *PropT) {
					fn(rt, sub.New(tb), mixedModelKeys(fx).Draw(rt, "key"))
				})
			})
	}
	return b.Seal(c.Method)
}

// RunMixed runs every check — the generated ones and any you
// wrote — against every implementation you pass it.
//
// Each argument describes one thing to do, in any order: an
// implementation to test, a table of your own checks, sample inputs to
// use, or checks to leave out.
//
//	RunMixed(t,
//		MixedHarness[*InMemory]{Name: "in-memory", New: NewInMemory},
//		MixedSuite.Without(MixedSuite.Checks.Store.Smoke()),
//	)
//
// Pass two implementations to compare them against each other, and mark
// the one you trust as the Oracle. Every check runs as its own subtest
// named after the implementation and the check, so `go test -run` can
// select one.
//
// A check that needs something your implementation has not supplied
// fails rather than skipping, and says which field to fill in. That is
// deliberate: a skipped check is how a claim goes unchecked while the
// run stays green.
func RunMixed(
	t *testing.T, opts ...MixedRunOpt,
) {
	t.Helper()
	var rc mixedRunConfig
	for _, o := range opts {
		o.applyTo(&rc)
	}
	fx := mixedNewFixture()
	for _, row := range rc.rows {
		rc.AddCheck(row.bind(fx))
	}
	// Checked here, after reading every argument and before running
	// anything: a misconfigured run reports all of its problems at once
	// rather than one per attempt.
	rc.Fail(t, "RunMixed")
	suite.Run(t,
		mixedSuite(fx).With(rc.Extra...).Without(rc.Drops...),
		rc.Subjects...)
}

// mixedProofs is every defect this run derived and can spell.
//
// Each is the smallest implementation that breaks exactly one claim: the
// generated double with one method overridden, and nothing else changed.
// The reason beside it is the substring the red must contain, so a defect
// that died on an unrelated guard stops counting as evidence.
//
// Unexported and built fresh per call. A defect carries a constructor
// that registers cleanup on the test it is handed, so a shared map would
// hand one test's cleanup to the next.
func mixedProofs() prove.Defects[Mixed] {
	ix := MixedSuite.Checks
	return prove.Defects[Mixed]{
		ix.Store.Smoke(): prove.One("a Mixed whose Store panics",
			func(tb testing.TB) Mixed {
				return NewMixedStub(tb, WithMixedStore(
					func(_ context.Context, _ pointintime.Value) error {
						panic("planted: Store panics")
					}))
			}).Reasoned(suite.RedPanicked),
		ix.Store.Cancels(): prove.One("a Mixed whose Store ignores the context it is handed",
			func(tb testing.TB) Mixed {
				return NewMixedStub(tb, WithMixedStore(
					func(_ context.Context, _ pointintime.Value) (err error) {
						// The call arrives and nothing is done with it; the bare
						// return answers every slot's zero, which for the error
						// slot is the nil this claim forbids.
						return
					}))
			}).Reasoned(suite.RedCancelled),
		ix.Store.NilContext(): prove.One("a Mixed whose Store forgives a nil context and answers",
			func(tb testing.TB) Mixed {
				return NewMixedStub(tb, WithMixedStore(
					func(_ context.Context, _ pointintime.Value) (err error) {
						// The call arrives and nothing is done with it; the bare
						// return answers every slot's zero, which for the error
						// slot is the nil this claim forbids.
						return
					}))
			}).Reasoned(suite.RedNilContext),
		ix.Store.Deadline(): prove.One("a Mixed whose Store ignores the context it is handed",
			func(tb testing.TB) Mixed {
				return NewMixedStub(tb, WithMixedStore(
					func(_ context.Context, _ pointintime.Value) (err error) {
						// The call arrives and nothing is done with it; the bare
						// return answers every slot's zero, which for the error
						// slot is the nil this claim forbids.
						return
					}))
			}).Reasoned(suite.RedDeadline),
		ix.Get.Smoke(): prove.One("a Mixed whose Get panics",
			func(tb testing.TB) Mixed {
				return NewMixedStub(tb, WithMixedGet(
					func(_ context.Context, _ string) (pointintime.Value, error) {
						panic("planted: Get panics")
					}))
			}).Reasoned(suite.RedPanicked),
		ix.Get.Cancels(): prove.One("a Mixed whose Get ignores the context it is handed",
			func(tb testing.TB) Mixed {
				return NewMixedStub(tb, WithMixedGet(
					func(_ context.Context, _ string) (r0 pointintime.Value, err error) {
						// The call arrives and nothing is done with it; the bare
						// return answers every slot's zero, which for the error
						// slot is the nil this claim forbids.
						return
					}))
			}).Reasoned(suite.RedCancelled),
		ix.Get.NilContext(): prove.One("a Mixed whose Get forgives a nil context and answers",
			func(tb testing.TB) Mixed {
				return NewMixedStub(tb, WithMixedGet(
					func(_ context.Context, _ string) (r0 pointintime.Value, err error) {
						// The call arrives and nothing is done with it; the bare
						// return answers every slot's zero, which for the error
						// slot is the nil this claim forbids.
						return
					}))
			}).Reasoned(suite.RedNilContext),
		ix.Get.Deadline(): prove.One("a Mixed whose Get ignores the context it is handed",
			func(tb testing.TB) Mixed {
				return NewMixedStub(tb, WithMixedGet(
					func(_ context.Context, _ string) (r0 pointintime.Value, err error) {
						// The call arrives and nothing is done with it; the bare
						// return answers every slot's zero, which for the error
						// slot is the nil this claim forbids.
						return
					}))
			}).Reasoned(suite.RedDeadline),
		ix.Get.ZeroOnError(): prove.One("a Mixed whose Get answers a believable value beside its error",
			func(tb testing.TB) Mixed {
				return NewMixedStub(tb, WithMixedGet(
					func(_ context.Context, _ string) (r0 pointintime.Value, err error) {
						// A believable answer beside the refusal. A caller
						// reading the error and one reading the value disagree
						// about what happened, which is the claim's own
						// violation rather than a subject that merely failed.
						r0 = pointintime.Value{Key: "other-value"}
						err = errors.New("planted: Get refused with a believable value")
						return
					}))
			}),
		ix.Get.Miss(): prove.One("a Mixed whose Get answers for an input nothing wrote",
			func(tb testing.TB) Mixed {
				return NewMixedStub(tb, WithMixedGet(
					func(_ context.Context, _ string) (r0 pointintime.Value, err error) {
						// A value for a call a correct subject answers nothing for.
						r0 = pointintime.Value{Key: "other-value"}
						return
					}))
			}),
		ix.Model.Agrees(): prove.One("a Mixed whose Store reports success and keeps nothing",
			func(tb testing.TB) Mixed {
				return NewMixedStub(tb, WithMixedStore(
					func(_ context.Context, _ pointintime.Value) (err error) {
						// The call arrives and nothing is done with it; the bare
						// return answers every slot's zero, which for the error
						// slot is the nil this claim forbids.
						return
					}))
			}),
		ix.Sim.Recovery(): prove.One("a Mixed whose rebuild finds an empty medium",
			func(testing.TB) Mixed {
				return NewMixedModelReference()
			}).RecoveringFresh(),
		ix.Model.WriteObservable(): prove.One("a Mixed whose Store reports success and keeps nothing",
			func(tb testing.TB) Mixed {
				return NewMixedStub(tb, WithMixedStore(
					func(_ context.Context, _ pointintime.Value) (err error) {
						// The call arrives and nothing is done with it; the bare
						// return answers every slot's zero, which for the error
						// slot is the nil this claim forbids.
						return
					}))
			}),
	}
}

// ProveMixed runs every check — the generated ones and any you
// wrote — against the deliberately broken implementation it names, and
// fails if the check does not catch it.
//
//	func TestMyChecksCanFail(t *testing.T) {
//		ProveMixed(t, MixedHarness[*InMemory]{Name: "in-memory", New: NewInMemory}, myChecks)
//	}
//
// A check that always passes is indistinguishable from a working one
// until something breaks in production. This is what tells them apart:
// give each check a ProvenBy, and this proves the check can fail.
//
// A check with no ProvenBy is not ignored — it has to say why, in
// Argued. The two are held level in both directions: claiming proof
// without a broken implementation fails here, and supplying one for a
// check that claims nothing fails too.
//
// It takes the same arguments RunMixed does, and for one reason: a
// check may need a capability, and the answer is a fact about this
// interface rather than about any one implementation. The harness is
// where you write it once. A planted defect stands in for a real
// subject, so it borrows the same answer rather than being asked for one
// of its own — which nothing here could supply.
func ProveMixed(
	t *testing.T, opts ...MixedRunOpt,
) {
	t.Helper()
	var rc mixedRunConfig
	for _, o := range opts {
		o.applyTo(&rc)
	}
	// The RUN's config, not the derived one: a check proven at default
	// pools carries no evidence about the pools a run actually uses.
	fx := mixedNewFixture()
	for _, row := range rc.rows {
		rc.AddCheck(row.bind(fx))
	}
	rc.Fail(t, "ProveMixed")
	s := mixedSuite(fx).With(rc.Extra...).Without(rc.Drops...)
	// Read off the subjects, because a door is answered once for the
	// interface and every subject of it reads the same answer.
	doors := suite.Doors(rc.Subjects...)
	defects := mixedProofs()
	for _, row := range rc.rows {
		if row.ProvenBy == nil {
			continue
		}
		bd, err := row.bind(fx)
		if err != nil {
			t.Fatalf("ProveMixed: %v", err)
		}
		sub, err := row.ProvenBy.Subject()
		if err != nil {
			t.Fatalf("ProveMixed: check %q: defect: %v", bd.ID, err)
		}
		defects[bd.ID] = prove.Defect[Mixed]{
			Subject: sub, Reason: row.ProvenReason,
		}
	}
	// A declined check takes its proof with it: proving a row the run was
	// told to leave out reports on a claim this package no longer makes,
	// and the parity gate fails naming a check the set does not hold.
	for _, id := range rc.Drops {
		delete(defects, id)
	}
	prove.All(t, s.Checks, defects.Answering(doors))
}

// GreenMixed runs every check — the generated ones and any you
// wrote — against an implementation that is CORRECT but different, and
// fails if a check rejects it.
//
//	func TestAnotherPolicyIsAllowed(t *testing.T) {
//		GreenMixed(t, suite.Subject[Mixed]{
//			Name: "evicts the newest", New: newNewestFirst,
//		})
//	}
//
// ProveMixed measures whether these checks can fire. This measures
// whether they fire SELECTIVELY. Nothing else here can tell a check that
// is right from one that is too strong: a check forbidding something the
// declaration permits looks exactly like a suite working, until somebody
// writes a legal implementation and it fails.
//
// The control is a real alternative, not a broken one — a different
// eviction victim, a delivery that duplicates where the contract allows
// it, a lazier evaluation behind the same boundary. Where a check
// genuinely cannot apply to your control, put its ID in the subject's
// Excused map: an excused check is skipped by name, because it yields no
// evidence either way.
//
// Same arguments as RunMixed, so the control meets the checks
// the run does — including the ones you wrote, which no caller can bind
// for themselves.
func GreenMixed(
	t *testing.T,
	control suite.Subject[Mixed],
	opts ...MixedRunOpt,
) {
	t.Helper()
	var rc mixedRunConfig
	for _, o := range opts {
		o.applyTo(&rc)
	}
	fx := mixedNewFixture()
	for _, row := range rc.rows {
		rc.AddCheck(row.bind(fx))
	}
	rc.Fail(t, "GreenMixed")
	s := mixedSuite(fx).With(rc.Extra...).Without(rc.Drops...)
	// Lent the doors the run answers, so a control is refused for being
	// wrong rather than for being unwired. Answering says why.
	prove.Green(t, s.Checks,
		control.Answering(suite.Doors(rc.Subjects...)))
}

// A second version check, for the leg idioms the rows above ride. The
// harness's own covers the check format; this one covers what a model row
// does with it. Regenerate the file to clear a mismatch.
var _ = legs.CompatV1

// mixedModelRows is what this package's model tier claims.
//
// Every row here needs sequences of calls judged against something
// outside the subject, which is what separates them from the rows
// above: those settle a claim with a fixed call sequence, and these
// cannot be stated that way at all. That is also why each takes the
// Subject rather than an instance — a sequence run builds its own, and
// some of them build two.
func mixedModelRows(fx MixedFixture) []suite.Check[Mixed] {
	return []suite.Check[Mixed]{
		{
			ID:          mixedCheckIndex.Model.Agrees(),
			Class:       suite.ClassDifferential,
			Claim:       "every operation sequence leaves the subject agreeing with the reference",
			Falsifiable: suite.Proven(),
			Strength:    suite.StrengthDifferential,
			RunWith: func(tb testing.TB, sub suite.Subject[Mixed]) {
				mixedAssertAgrees(tb, sub, fx)
			},
		},
		{
			ID:          mixedCheckIndex.Model.Linearizable(),
			Class:       suite.ClassConcurrent,
			Claim:       "concurrent operation histories are linearizable",
			Falsifiable: suite.Argued("no mechanical rule plants a defect for this claim; the ones that would are domain composites, which no rule reaches from shape and stamps alone"),
			Strength:    suite.StrengthDifferential,
			RunWith: func(tb testing.TB, sub suite.Subject[Mixed]) {
				mixedAssertLinearizable(tb, sub, fx)
			},
		},
		{
			ID:    mixedCheckIndex.Sim.Recovery(),
			Class: suite.ClassSimRecovery,
			Claim: "every acknowledged write is still readable after the process is rebuilt over its medium",
			Needs: suite.Caps{
				suite.CapRecover: nil,
			},
			Falsifiable: suite.Proven(),
			Strength:    suite.StrengthDifferential,
			RunWith: func(tb testing.TB, sub suite.Subject[Mixed]) {
				mixedAssertRecovery(tb, sub, fx)
			},
		},
		{
			ID:    mixedCheckIndex.Model.WriteObservable(),
			Class: suite.ClassLaws,
			Claim: "a written value is readable under the key it was written with",
			Binds: []string{
				lawid.WriteObservable,
			},
			Falsifiable: suite.Proven(),
			Strength:    suite.StrengthDifferential,
			RunWith: func(tb testing.TB, sub suite.Subject[Mixed]) {
				mixedAssertWriteObservable(tb, sub, fx)
			},
		},
		{
			ID:    mixedCheckIndex.Model.PointInTime(),
			Class: suite.ClassLaws,
			Claim: "a read at a time answers what was committed at or before it",
			Binds: []string{
				lawid.PointInTime,
			},
			Falsifiable: suite.Argued("no mechanical rule plants a defect for this claim; the ones that would are domain composites, which no rule reaches from shape and stamps alone"),
			Strength:    suite.StrengthDifferential,
			RunWith: func(tb testing.TB, sub suite.Subject[Mixed]) {
				mixedAssertPointInTime(tb, sub, fx)
			},
		},
	}
}

// --- Mixed's model tier -------------------------------------------
//
// Random sequences of Mixed's methods, run against every subject and
// something that judges them from outside. The rows on the run surface
// above carry it, and MixedSuite.Without declines any of them by name.
//
//	Reference: derived — a keyed map over the Value fixture pair,
//	           keyed on Key; NewMixedModelReference replaces it
//	Sequences: Store (writer), Get (reader)
//	Values:    the fixture pair blended with arbitrary draws, each keyed
//	           from the pool

// mixedModelKeys is the key pool every key slot draws from.
//
// Two keys, and deliberately not more: collision density is what makes a
// read revisit a write and an overwrite land on held state. A wide key
// pool would pass every comparison over a history that never collides.
func mixedModelKeys(fx MixedFixture) *model.Generator[string] {
	// Widened unconditionally: this run emits no config, so there is no
	// pool a consumer could have narrowed and nothing to gate on. The
	// provenance argument applies to a pool somebody passed, and nobody
	// can pass one here.
	return legs.Blend(true,
		model.SampledFrom([]string{fx.Key(), fx.KeyOther()}),
		func(s string) string { return string(s) },
	)
}

// mixedModelValues is the value pool every value slot draws from.
//
// The fixture pair blended with arbitrary draws: the pair keeps identical
// rewrites frequent, the wide arm reaches values no fixture spells, and
// nothing in the claims licenses refusing either.
func mixedModelValues(fx MixedFixture) *model.Generator[pointintime.Value] {
	keys := mixedModelKeys(fx)
	bodies := model.OneOf(
		model.SampledFrom([]pointintime.Value{fx.Value(), fx.ValueOther()}),
		model.Make[pointintime.Value](),
	)
	// Every drawn value lands on a pooled key: a key rewritten under
	// another body is the history latest-write-wins is about, and a
	// fresh-keyed value would never collide with one already held.
	return model.Custom(func(t *model.T) pointintime.Value {
		v := bodies.Draw(t, "value_body")
		v.Key = keys.Draw(t, "value_key")
		return v
	})
}

// mixedModelMiss is what the reference reports for a key nothing
// wrote. Only its presence is compared — a subject reports its own miss
// sentinel, and the run asks whether both sides missed, not how they spelled
// it. Where the declaration stamps a sentinel of its own, the oracle takes
// that identity instead and this var is not declared.
var mixedModelMiss = errors.New("mixed: the model reference holds nothing under the key")

// mixedModelKeyOf projects a value's identity — the one derivation the
// reference keys on and every keyed law reuses, so the two cannot disagree
// about which field is the key.
func mixedModelKeyOf(v pointintime.Value) string {
	return v.Key
}

// mixedModelReference adapts the shipped MapStore oracle to Mixed.
// Deliberately simple: its correctness is read, not tested.
type mixedModelReference struct {
	store *ref.MapStore[string, pointintime.Value]
}

// NewMixedModelReference builds one. Exported because a consumer whose
// semantics outrun their shape replaces it, and because the proof beside
// this file drives it as a subject of its own.
func NewMixedModelReference() Mixed {
	return &mixedModelReference{store: ref.NewMapStore[string, pointintime.Value](
		mixedModelKeyOf,
		mixedModelMiss,
	)}
}

func (r *mixedModelReference) Store(ctx context.Context, v pointintime.Value) error {
	return r.store.Put(ctx, v)
}

func (r *mixedModelReference) Get(ctx context.Context, key string) (pointintime.Value, error) {
	return r.store.Get(ctx, key)
}

// mixedModelActions is the operation vocabulary both legs drive.
//
// One constructor per method shape, from the engine's action set rather
// than hand-written closures: the constructors record inputs and outputs
// into the trace a law reads, compare the two sides the same way for every
// action, and shrink a failing sequence to the shortest one that still
// fails.
func mixedModelActions(fx MixedFixture) []model.Action[Mixed] {
	keys := mixedModelKeys(fx)
	values := mixedModelValues(fx)
	return []model.Action[Mixed]{
		action.Writer("Store", values,
			func(ctx context.Context, s pointintime.Mixed, v pointintime.Value) error {
				return s.Store(ctx, v)
			}),
		action.Reader("Get", keys,
			func(ctx context.Context, s pointintime.Mixed, k string) (pointintime.Value, error) {
				return s.Get(ctx, k)
			}),
	}
}

// mixedAssertAgrees drives random operation sequences against the subject and
// the reference, comparing after every call.
//
// The differential is the strongest oracle this tier has, and it is this
// leg's whole job: no laws are registered, so nothing competes with it and
// a disagreement is what ends the run.
func mixedAssertAgrees(
	tb testing.TB,
	sub suite.Subject[Mixed],
	fx MixedFixture,
) {
	tb.Helper()
	legs.Differential(tb, sub,
		NewMixedModelReference,
		mixedModelActions(fx))
}

// mixedAssertLinearizable drives concurrent workers against one instance and asks
// whether the history they recorded has a serial explanation.
//
// A claim no sequential leg can state. The differential compares one
// ordered run against a reference and the laws hold after each step of
// one; this is about what a caller may observe when there is no single
// order at all, and the model is what decides whether one exists.
//
// The engine owns the interleaving, the property loop and the artifact a
// failing history is written to. This supplies the verbs and the model.
func mixedAssertLinearizable(
	tb testing.TB,
	sub suite.Subject[Mixed],
	fx MixedFixture,
) {
	tb.Helper()
	keys := mixedModelKeys(fx)
	values := mixedModelValues(fx)
	legs.Concurrent(tb, sub,
		NewMixedModelReference,
		model.ConcurrentConfig[Mixed]{
			Model: linearize.KV[string, pointintime.Value](nil),
			Actions: []model.ConcurrentAction[Mixed]{
				linearize.ConcurrentReader(linearize.OpGet, keys,
					func(ctx context.Context, s pointintime.Mixed, k string) (pointintime.Value, error) {
						return s.Get(ctx, k)
					}),
				linearize.ConcurrentWriter(linearize.OpPut, values,
					func(ctx context.Context, s pointintime.Mixed, v pointintime.Value) error {
						return s.Store(ctx, v)
					},
					mixedModelKeyOf),
			},
		})
}

// mixedAssertRecovery drives a drawn schedule of writes, reads and crashes,
// and asks whether the medium still owes what the writes promised.
//
// A claim no other leg in this file can state. The differential compares
// two live instances and the laws hold after each step of one; this is
